ignore={'.git','.venv','venv','node_modules','__pycache__','.mypy_cache','.pytest_cache','dist','build'}
bad=[]
for p in pathlib.Path('.').rglob('*.py'):
    if any(part in ignore for part in p.parts): continue
    try: ast.parse(p.read_text(encoding='utf-8', errors='ignore'))
    except Exception as e: bad.append(f'{p}: {e}')
print('\n'.join(bad))
sys.exit(1 if bad else 0)
